--
-- Name: dept_performance; Type: MATERIALIZED VIEW; Schema: public; Owner: abdullah
--

CREATE MATERIALIZED VIEW public.dept_performance AS
 SELECT d.department_id,
    d.department_code,
    d.department_name,
    d.specialty_type,
    count(DISTINCT pt.patient_id) AS total_patients,
    count(DISTINCT
        CASE
            WHEN (p.risk_tier >= 4) THEN p.patient_id
            ELSE NULL::bigint
        END) AS high_risk_patients,
        CASE
            WHEN (count(DISTINCT pt.patient_id) > 0) THEN round(((100.0 * (count(DISTINCT
            CASE
                WHEN (p.risk_tier >= 4) THEN p.patient_id
                ELSE NULL::bigint
            END))::numeric) / (count(DISTINCT pt.patient_id))::numeric), 2)
            ELSE (0)::numeric
        END AS high_risk_percentage,
    round(avg(pt.annual_cost), 2) AS avg_patient_cost,
    sum(pt.annual_cost) AS total_dept_cost,
    round(avg(pf.complexity_index), 2) AS avg_complexity_index,
    round(avg(pf.frailty_score), 2) AS avg_frailty_score,
    round(avg(fp.roi_percent), 2) AS avg_roi_percent,
    count(
        CASE
            WHEN (fp.roi_percent > (0)::numeric) THEN 1
            ELSE NULL::integer
        END) AS positive_roi_predictions,
    count(
        CASE
            WHEN (fp.roi_percent > (25)::numeric) THEN 1
            ELSE NULL::integer
        END) AS strong_roi_predictions,
    sum(fp.expected_savings) AS total_potential_savings,
    count(DISTINCT p.prediction_window) AS prediction_windows_covered,
    max(p.prediction_timestamp) AS last_update_date
   FROM ((((public.departments d
     LEFT JOIN public.patients pt ON ((d.department_id = pt.department_id)))
     LEFT JOIN public.predictions p ON ((pt.patient_id = p.patient_id)))
     LEFT JOIN public.patient_features pf ON ((pt.patient_id = pf.patient_id)))
     LEFT JOIN public.financial_projections fp ON ((p.prediction_id = fp.prediction_id)))
  WHERE ((pt.is_active = true) OR ((pt.patient_id IS NULL) AND (p.is_active = true)) OR (p.prediction_id IS NULL))
  GROUP BY d.department_id, d.department_code, d.department_name, d.specialty_type
  ORDER BY (sum(fp.expected_savings)) DESC, d.department_name
  WITH NO DATA;


ALTER TABLE public.dept_performance OWNER TO abdullah;

