CREATE MATERIALIZED VIEW public.dept_risk_distribution AS
 SELECT d.department_id,
    d.department_code,
    d.department_name,
    d.specialty_type,
    p.prediction_window,
    p.risk_tier,
    count(DISTINCT p.patient_id) AS patient_count,
        CASE
            WHEN (sum(count(DISTINCT p.patient_id)) OVER (PARTITION BY d.department_id, p.prediction_window) > (0)::numeric) THEN round(((100.0 * (count(DISTINCT p.patient_id))::numeric) / sum(count(DISTINCT p.patient_id)) OVER (PARTITION BY d.department_id, p.prediction_window)), 2)
            ELSE (0)::numeric
        END AS percentage_in_dept_window,
    round(avg(pt.annual_cost), 2) AS avg_annual_cost,
    sum(pf.complexity_index) AS total_complexity,
    round(avg(pf.complexity_index), 2) AS avg_complexity,
    round(avg(fp.roi_percent), 2) AS avg_roi_percent,
    count(
        CASE
            WHEN (fp.roi_percent > (0)::numeric) THEN 1
            ELSE NULL::integer
        END) AS positive_roi_count,
    min(p.prediction_timestamp) AS first_prediction_date
   FROM ((((public.departments d
     LEFT JOIN public.patients pt ON ((d.department_id = pt.department_id)))
     LEFT JOIN public.predictions p ON ((pt.patient_id = p.patient_id)))
     LEFT JOIN public.patient_features pf ON ((pt.patient_id = pf.patient_id)))
     LEFT JOIN public.financial_projections fp ON ((p.prediction_id = fp.prediction_id)))
  WHERE ((p.is_active = true) OR ((p.prediction_id IS NULL) AND (pt.is_active = true)) OR (pt.patient_id IS NULL))
  GROUP BY d.department_id, d.department_code, d.department_name, d.specialty_type, p.prediction_window, p.risk_tier
  ORDER BY d.department_name, p.prediction_window, p.risk_tier DESC
