CREATE MATERIALIZED VIEW public.high_risk_by_department AS
 SELECT d.department_id,
    d.department_code,
    d.department_name,
    d.specialty_type,
    p.prediction_window,
    p.risk_tier,
    count(DISTINCT p.patient_id) AS high_risk_patient_count,
    round(avg(pt.annual_cost), 2) AS avg_cost_per_patient,
    sum(pt.annual_cost) AS total_cost_at_risk,
    round(avg(pf.complexity_index), 2) AS avg_complexity,
    round(avg(pf.frailty_score), 2) AS avg_frailty,
    round(avg(fp.roi_percent), 2) AS avg_roi_percent,
    sum(fp.expected_savings) AS total_potential_savings,
    max(p.prediction_timestamp) AS last_prediction_date
   FROM ((((public.departments d
     JOIN public.patients pt ON ((d.department_id = pt.department_id)))
     JOIN public.predictions p ON ((pt.patient_id = p.patient_id)))
     JOIN public.patient_features pf ON ((pt.patient_id = pf.patient_id)))
     JOIN public.financial_projections fp ON ((p.prediction_id = fp.prediction_id)))
  WHERE ((p.is_active = true) AND (fp.is_active = true) AND (p.risk_tier >= 4))
  GROUP BY d.department_id, d.department_code, d.department_name, d.specialty_type, p.prediction_window, p.risk_tier
  ORDER BY (sum(pt.annual_cost)) DESC, d.department_name, p.prediction_window, p.risk_tier DESC
