--
-- Name: org_tier_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: abdullah
--

CREATE MATERIALIZED VIEW public.org_tier_summary AS
 SELECT p.prediction_window,
    count(DISTINCT p.patient_id) AS patient_count,
    count(DISTINCT p.risk_tier) AS tier_count,
    max(
        CASE
            WHEN (p.risk_tier = 5) THEN 1
            ELSE 0
        END) AS has_critical,
    sum(
        CASE
            WHEN (p.risk_tier >= 4) THEN 1
            ELSE 0
        END) AS high_risk_count,
    round(((100.0 * (sum(
        CASE
            WHEN (p.risk_tier >= 4) THEN 1
            ELSE 0
        END))::numeric) / (count(DISTINCT p.patient_id))::numeric), 2) AS high_risk_percentage,
    sum(fp.expected_savings) AS total_addressable_opportunity,
    round(avg(fp.roi_percent), 2) AS avg_roi_percent,
    min(p.prediction_timestamp) AS first_prediction_date,
    max(p.prediction_timestamp) AS last_prediction_date
   FROM (public.predictions p
     LEFT JOIN public.financial_projections fp ON ((p.prediction_id = fp.prediction_id)))
  WHERE (p.is_active = true)
  GROUP BY p.prediction_window
  ORDER BY
        CASE
            WHEN ((p.prediction_window)::text = '30_day'::text) THEN 1
            WHEN ((p.prediction_window)::text = '60_day'::text) THEN 2
            WHEN ((p.prediction_window)::text = '90_day'::text) THEN 3
            ELSE NULL::integer
        END
  WITH NO DATA;


ALTER TABLE public.org_tier_summary OWNER TO abdullah;

