--
-- Name: positive_roi_patients; Type: MATERIALIZED VIEW; Schema: public; Owner: abdullah
--

CREATE MATERIALIZED VIEW public.positive_roi_patients AS
 SELECT pt.patient_id,
    pt.external_id,
    org.organization_code,
    org.organization_name,
    d.department_code,
    d.department_name,
    p.prediction_window,
    p.risk_tier,
    pt.age,
    pt.gender,
    pt.race,
    pt.annual_cost,
    pf.complexity_index,
    pf.frailty_score,
    fp.window_cost,
    fp.addressable_cost,
    fp.intervention_cost,
    fp.expected_savings,
    fp.net_benefit,
    fp.roi_percent,
    fp.roi_category,
    p.prediction_timestamp AS prediction_date
   FROM (((((public.patients pt
     JOIN public.organizations org ON ((pt.organization_id = org.organization_id)))
     JOIN public.departments d ON ((pt.department_id = d.department_id)))
     JOIN public.predictions p ON ((pt.patient_id = p.patient_id)))
     JOIN public.patient_features pf ON ((pt.patient_id = pf.patient_id)))
     JOIN public.financial_projections fp ON ((p.prediction_id = fp.prediction_id)))
  WHERE ((p.is_active = true) AND (fp.is_active = true) AND (fp.roi_percent > (0)::numeric))
  ORDER BY fp.roi_percent DESC, pt.annual_cost DESC
  WITH NO DATA;


ALTER TABLE public.positive_roi_patients OWNER TO abdullah;

