--
-- Name: roi_aggregations; Type: MATERIALIZED VIEW; Schema: public; Owner: abdullah
--

CREATE MATERIALIZED VIEW public.roi_aggregations AS
 SELECT fp.prediction_window,
    count(DISTINCT fp.patient_id) AS intervention_eligible_count,
    sum(fp.window_cost) AS total_cost,
    sum(fp.addressable_cost) AS total_addressable_cost,
    sum(fp.intervention_cost) AS total_intervention_cost,
    sum(fp.expected_savings) AS total_expected_savings,
    sum(fp.net_benefit) AS total_net_benefit,
    round(avg(fp.roi_percent), 2) AS avg_roi_percent,
    round(max(fp.roi_percent), 2) AS max_roi_percent,
    round(min(fp.roi_percent), 2) AS min_roi_percent,
    count(
        CASE
            WHEN ((fp.roi_category)::text = 'EXCELLENT'::text) THEN 1
            ELSE NULL::integer
        END) AS excellent_roi_count,
    count(
        CASE
            WHEN ((fp.roi_category)::text = 'STRONG'::text) THEN 1
            ELSE NULL::integer
        END) AS strong_roi_count,
    count(
        CASE
            WHEN ((fp.roi_category)::text = 'POSITIVE'::text) THEN 1
            ELSE NULL::integer
        END) AS positive_roi_count,
    count(
        CASE
            WHEN ((fp.roi_category)::text = 'NO_ROI'::text) THEN 1
            ELSE NULL::integer
        END) AS no_roi_count
   FROM public.financial_projections fp
  WHERE (fp.is_active = true)
  GROUP BY fp.prediction_window
  ORDER BY
        CASE
            WHEN ((fp.prediction_window)::text = '30_day'::text) THEN 1
            WHEN ((fp.prediction_window)::text = '60_day'::text) THEN 2
            WHEN ((fp.prediction_window)::text = '90_day'::text) THEN 3
            ELSE NULL::integer
        END
  WITH NO DATA;


ALTER TABLE public.roi_aggregations OWNER TO abdullah;

--
-- Name: tier_financial_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: abdullah
--

CREATE MATERIALIZED VIEW public.tier_financial_summary AS
 SELECT pred.prediction_window,
    fp.risk_tier,
        CASE fp.risk_tier
            WHEN 1 THEN 'Tier 1 - Low Risk'::text
            WHEN 2 THEN 'Tier 2 - Low-Moderate'::text
            WHEN 3 THEN 'Tier 3 - Moderate'::text
            WHEN 4 THEN 'Tier 4 - High'::text
            WHEN 5 THEN 'Tier 5 - Critical'::text
            ELSE NULL::text
        END AS tier_name,
    count(*) AS patient_count,
    round(avg(pred.risk_score), 4) AS avg_risk_score,
    sum(fp.window_cost) AS total_projected_cost,
    sum(fp.intervention_cost) AS total_intervention_cost,
    sum(fp.expected_savings) AS total_expected_savings,
    sum(fp.net_benefit) AS total_net_benefit,
    round(((sum(fp.net_benefit) / NULLIF(sum(fp.intervention_cost), (0)::numeric)) * (100)::numeric), 2) AS tier_roi_percent,
    round(avg(fp.success_rate), 4) AS avg_success_rate
   FROM (public.predictions pred
     JOIN public.financial_projections fp ON ((pred.prediction_id = fp.prediction_id)))
  GROUP BY pred.prediction_window, fp.risk_tier
  ORDER BY pred.prediction_window, fp.risk_tier
  WITH NO DATA;


ALTER TABLE public.tier_financial_summary OWNER TO abdullah;

